descriptor.templateCss:
/* General Styles */
body {
  font-family: Arial, sans-serif;
  margin: 0;
  padding: 0;
  display: flex;
}

.sidebar {
  width: 250px;
  background-color: #D3D3D3; /* Light Grey */
  color: black;
  padding-top: 20px;
  display: flex;
  flex-direction: column;
  align-items: center;
}

.logo {
  width: 200px;
  height: auto;
  margin-bottom: 20px;
}

.sidebar ul {
  list-style-type: none;
  padding: 0;
  width: 100%;
}

.sidebar ul li {
  width: 100%;
}

.sidebar ul li a {
  display: block;
  padding: 10px 20px;
  text-decoration: none;
  color: black;
  font-size: 18px;
  background-color: #E0E0E0; /* Slightly darker grey */
  border: 1px solid #C0C0C0; /* Light border for separation */
  width: 100%;
}

.sidebar ul li a:hover {
  background-color: #B0B0B0; /* Darker grey on hover */
}

.main-content {
  flex-grow: 1;
  padding: 20px;
  width: 100%;
}

.main-content h1 {
  font-size: 24px;
}

.main-content ul {
  list-style-type: none;
  padding: 0;
}

.main-content ul li {
  font-size: 18px;
}

